//! Interop tests against real Xray-core and sing-box REALITY servers.
//!
//! These tests are ignored by default; the `REALITY interop (Linux)` CI job
//! starts the servers and targets and runs them with `--ignored`. Inputs:
//!
//! * `NC_INTEROP_SERVERS`: `name=host:port:flow,...` with flow `vision` or `none`
//! * `NC_VLESS_UUID`, `NC_REALITY_PUBLIC_KEY`, `NC_REALITY_SHORT_ID`,
//!   `NC_REALITY_SERVER_NAME`
//! * `NC_HTTP_TARGET` (plain HTTP/1.0 server) and `NC_TLS_TARGET`
//!   (`openssl s_server -WWW`, TLS 1.3), both serving `/payload.bin`
//!   generated by [`expected_payload`].

use std::io;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Duration;

use engine_outbound::{TargetAddr, TcpDialer, TcpOutbound};
use outbound_vless::{
    parse_public_key, parse_short_id, parse_uuid, Flow, RealityConfig, VlessRealityConfig,
    VlessRealityOutbound,
};
use tls_mimic::{ClientConfig, Fingerprint, HandshakeHooks};
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};

const PAYLOAD_LEN: usize = 1_000_000;
const TIMEOUT: Duration = Duration::from_secs(60);

fn expected_payload() -> Vec<u8> {
    (0..PAYLOAD_LEN)
        .map(|i| ((i * 7 + 3) % 251) as u8)
        .collect()
}

fn env(name: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| panic!("{name} must be set for interop tests"))
}

struct Server {
    name: String,
    config: VlessRealityConfig,
}

fn servers() -> Vec<Server> {
    let uuid = parse_uuid(&env("NC_VLESS_UUID")).unwrap();
    let public_key = parse_public_key(&env("NC_REALITY_PUBLIC_KEY")).unwrap();
    let short_id = parse_short_id(&env("NC_REALITY_SHORT_ID")).unwrap();
    let server_name = env("NC_REALITY_SERVER_NAME");
    env("NC_INTEROP_SERVERS")
        .split(',')
        .map(|entry| {
            let (name, rest) = entry.split_once('=').expect("name=host:port:flow");
            let mut parts = rest.rsplitn(3, ':');
            let flow = match parts.next().unwrap() {
                "vision" => Flow::Vision,
                "none" => Flow::None,
                other => panic!("unknown flow {other}"),
            };
            let port: u16 = parts.next().unwrap().parse().unwrap();
            let host = parts.next().unwrap().to_owned();
            Server {
                name: name.to_owned(),
                config: VlessRealityConfig {
                    server: host,
                    port,
                    uuid,
                    flow,
                    reality: RealityConfig::new(server_name.clone(), public_key, short_id),
                },
            }
        })
        .collect()
}

fn target(name: &str) -> TargetAddr {
    TargetAddr::from(env(name).parse::<SocketAddr>().unwrap())
}

/// Test-only verifier for the self-signed inner target.
struct AcceptAnyCertificate;

impl HandshakeHooks for AcceptAnyCertificate {
    fn verify_server_certificates(
        &mut self,
        _server_name: &str,
        _chain: &[Vec<u8>],
    ) -> io::Result<()> {
        Ok(())
    }
}

async fn http_get<S: AsyncRead + AsyncWrite + Unpin>(stream: &mut S) -> io::Result<Vec<u8>> {
    stream
        .write_all(b"GET /payload.bin HTTP/1.0\r\nHost: interop.test\r\n\r\n")
        .await?;
    stream.flush().await?;
    let mut response = Vec::new();
    stream.read_to_end(&mut response).await?;
    let split = response
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "no HTTP header terminator"))?;
    let status = String::from_utf8_lossy(&response[..split]).to_string();
    assert!(
        status.starts_with("HTTP/1.0 200") || status.starts_with("HTTP/1.1 200"),
        "unexpected status: {status}"
    );
    Ok(response[split + 4..].to_vec())
}

async fn with_timeout<T>(future: impl std::future::Future<Output = T>) -> T {
    tokio::time::timeout(TIMEOUT, future)
        .await
        .expect("interop step timed out")
}

#[tokio::test(flavor = "current_thread")]
#[ignore = "needs the REALITY interop CI environment"]
async fn tls_mimic_completes_a_handshake_with_openssl() {
    let target = env("NC_TLS_TARGET");
    let transport = tokio::net::TcpStream::connect(&target).await.unwrap();
    let mut tls = with_timeout(tls_mimic::connect(
        transport,
        &ClientConfig::new("target.interop.test", Fingerprint::Chrome),
        &mut AcceptAnyCertificate,
    ))
    .await
    .unwrap();
    let body = with_timeout(http_get(&mut tls)).await.unwrap();
    assert_eq!(body, expected_payload());
}

/// Runs `check` against every server and reports all failures together, so
/// one incompatible server does not hide the results of the others.
async fn for_each_server<F, Fut>(check: F)
where
    F: Fn(Server) -> Fut,
    Fut: std::future::Future<Output = Result<String, String>>,
{
    let mut failures = Vec::new();
    for server in servers() {
        let name = server.name.clone();
        match tokio::time::timeout(TIMEOUT, check(server)).await {
            Ok(Ok(summary)) => eprintln!("{name}: {summary}"),
            Ok(Err(error)) => {
                eprintln!("{name}: FAILED: {error}");
                failures.push(format!("{name}: {error}"));
            }
            Err(_) => {
                eprintln!("{name}: FAILED: timed out");
                failures.push(format!("{name}: timed out"));
            }
        }
    }
    assert!(failures.is_empty(), "failing servers: {failures:#?}");
}

#[tokio::test(flavor = "current_thread")]
#[ignore = "needs the REALITY interop CI environment"]
async fn plain_http_through_each_reality_server() {
    for_each_server(|server| async move {
        let outbound = VlessRealityOutbound::new(server.config, Arc::new(TcpDialer));
        let mut stream = outbound
            .connect(&target("NC_HTTP_TARGET"))
            .await
            .map_err(|error| format!("connect failed: {error}"))?;
        let body = http_get(&mut stream)
            .await
            .map_err(|error| format!("HTTP failed: {error}"))?;
        if body != expected_payload() {
            return Err(format!("payload mismatch ({} bytes)", body.len()));
        }
        Ok("plain HTTP ok".to_owned())
    })
    .await;
}

#[tokio::test(flavor = "current_thread")]
#[ignore = "needs the REALITY interop CI environment"]
async fn inner_tls13_through_each_reality_server_uses_vision_direct_copy() {
    for_each_server(|server| async move {
        // Xray only switches the downlink to direct when a read from the
        // target starts on an application-data record boundary, which depends
        // on TCP segmentation. Retry that case; every attempt still has to
        // deliver the exact payload.
        let mut attempt = 1;
        loop {
            match inner_tls13_direct_copy(server.config.clone()).await {
                Err(error) if error == DOWNLINK_NOT_DIRECT && attempt < DIRECT_ATTEMPTS => {
                    eprintln!("{}: attempt {attempt}: {error}, retrying", server.name);
                    attempt += 1;
                }
                result => return result,
            }
        }
    })
    .await;
}

const DIRECT_ATTEMPTS: usize = 3;
const DOWNLINK_NOT_DIRECT: &str = "downlink did not switch to direct";

async fn inner_tls13_direct_copy(config: VlessRealityConfig) -> Result<String, String> {
    let flow = config.flow;
    let outbound = VlessRealityOutbound::new(config, Arc::new(TcpDialer));
    let vless = outbound
        .connect_stream(&target("NC_TLS_TARGET"))
        .await
        .map_err(|error| format!("connect failed: {error}"))?;
    let mut inner = tls_mimic::connect(
        vless,
        &ClientConfig::new("target.interop.test", Fingerprint::Chrome),
        &mut AcceptAnyCertificate,
    )
    .await
    .map_err(|error| format!("inner TLS failed: {error}"))?;
    let body = http_get(&mut inner)
        .await
        .map_err(|error| format!("HTTPS failed: {error}"))?;
    if body != expected_payload() {
        return Err(format!("payload mismatch ({} bytes)", body.len()));
    }
    let vless = inner.get_ref();
    if flow == Flow::Vision {
        let state = vless.vision_state().unwrap();
        if !state.enable_xtls {
            return Err("inner TLS 1.3 not detected".to_owned());
        }
        if !vless.is_direct_write() {
            return Err("uplink did not switch to direct".to_owned());
        }
        if !vless.is_direct_read() {
            return Err(DOWNLINK_NOT_DIRECT.to_owned());
        }
    } else if vless.is_direct_write() || vless.is_direct_read() {
        return Err("plain flow switched to direct".to_owned());
    }
    Ok(format!("inner TLS 1.3 ok (flow {flow:?})"))
}

#[tokio::test(flavor = "current_thread")]
#[ignore = "needs the REALITY interop CI environment"]
async fn wrong_public_key_is_rejected_without_sending_proxy_traffic() {
    for server in servers() {
        let mut config = server.config.clone();
        config.reality.public_key[0] ^= 0x55;
        let outbound = VlessRealityOutbound::new(config, Arc::new(TcpDialer));
        let result = with_timeout(outbound.connect(&target("NC_HTTP_TARGET"))).await;
        match result {
            Ok(_) => panic!("{}: connection with a wrong key succeeded", server.name),
            Err(error) => {
                assert_eq!(
                    error.kind(),
                    io::ErrorKind::PermissionDenied,
                    "{}: {error}",
                    server.name
                );
                eprintln!("{}: wrong key rejected ({error})", server.name);
            }
        }
    }
}
